// #e0da25 (6a993d6e89df7f29e9e0da25) — пункт реджекта 13.10: обрыв HTTP ~20 с посреди официального звонка (WebRTC жив).
// Кейс REC-030. Повторяет звонок C4 21.10 (QA-C4-2110-D2): на ~20-й с context.setOffline(true) на 20 с, затем online.
// Ожидаемо: куски, не ушедшие во время обрыва, догружаются после восстановления; клиент сообщает failed:[] и complete:true;
// is_partial=false; в отчёте нет «ההקלטה חלקית»; файл записи ≈ длительности звонка (дыра 15 с не допускается, допуск 10 с);
// клик по реплике после обрыва ставит плеер на её начало.
// @data, НЕ prod-safe: создаёт кандидата «QA-AUTO-HB-…» (link_only, без письма/SMS), тратит официальный звонок и AI (~6–9 мин).
// Кандидат не удаляется (правило проекта — только с «да»). Симуляция: QA_CALL_SIMULATION (по умолчанию «מערכות סולאריות»).
// Ветка «кусок так и не загрузился → is_partial=true + «ההקלטה חלקית»» — REC-013 (готовые данные) и ручной REC-031.
import { Request } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { createCandidateLink, tap } from '../candidate-call/support';
import { launchGuest, startOfficialCall, okParts, expectAllPartsUploaded, openBusinessApi, candidateId, waitTranscriptAndReport, checkReportPage } from './support';

const TAG = '#e0da25 · #6a993d6e89df7f29e9e0da25';
const PARTS_BEFORE_DROP = 4; // часть ≈ каждые 5 с → обрыв на ~20-й с (как C4)
const OUTAGE_MS = 20_000; // длительность обрыва из реджекта 13.10 («לכ-20 שניות») — это условие сценария, а не ожидание результата
const PARTS_AFTER_DROP = 12; // ещё ≥ ~60 с разговора после восстановления

type EndBody = { technical_log?: { recording?: { parts?: number; failed?: number[]; complete?: boolean } } };

test.describe(`Запись звонка — обрыв HTTP ~20 с посреди звонка (${TAG}) @call`, () => {
  test(`REC-030: обрыв HTTP 20 с на ~20-й с → куски догружены, failed:[], is_partial=false, без «ההקלטה חלקית», файл ≈ звонку, клик по реплике после обрыва @desktop @data ${TAG}`, async ({ asUser }) => {
    test.setTimeout(20 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-HB-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}» (официальный звонок использован), не удаляется` });

    const guest = await launchGuest();
    let failedDuringOutage = 0;
    let offline = false;
    let endReq: EndBody | undefined;
    guest.page.on('requestfailed', (r: Request) => {
      if (offline && r.url().includes('recording-upload-url')) failedDuringOutage++;
    });
    guest.page.on('request', (r: Request) => {
      if (r.method() === 'POST' && r.url().includes('/functions/v1/end-candidate-attempt')) endReq = r.postDataJSON() as EndBody;
    });

    try {
      await startOfficialCall(guest.page, link);
      await expect
        .poll(() => okParts(guest.log).size, { message: `меньше ${PARTS_BEFORE_DROP} частей до обрыва`, timeout: 2 * 60_000, intervals: [1_000] })
        .toBeGreaterThanOrEqual(PARTS_BEFORE_DROP);

      // Обрыв HTTP: сеть страницы offline, WebRTC-соединение не закрывается (так было в C4 21.10).
      const partsAtDrop = Math.max(...okParts(guest.log)) + 1;
      offline = true;
      await guest.page.context().setOffline(true);
      await guest.page.waitForTimeout(OUTAGE_MS);
      await guest.page.context().setOffline(false);
      offline = false;
      expect(failedDuringOutage, 'обрыв не сработал: ни один запрос recording-upload-url не упал').toBeGreaterThan(0);

      // Звонок продолжается после восстановления.
      await expect(guest.page.getByRole('button', { name: 'לסיים שיחה' })).toBeVisible();
      await expect
        .poll(() => okParts(guest.log).size, { message: 'после восстановления куски не догружаются', timeout: 3 * 60_000, intervals: [2_000] })
        .toBeGreaterThanOrEqual(partsAtDrop + PARTS_AFTER_DROP);

      await tap(guest.page, 'לסיים שיחה');
      await tap(guest.page, 'לאשר סיום שיחה');
      await expect(guest.page.getByText('הסימולציה הושלמה')).toBeVisible({ timeout: 120_000 });
      await expect.poll(() => guest.log.endRespAt, { message: 'нет ответа end-candidate-attempt', timeout: 120_000 }).toBeTruthy();

      // Источник: реджект 13.10 п.1–2 + AC1 «מוקלטת במלואה» / треб.1 «חלקים שלא נטענו בזמן ניתוק קצר… נטענים מחדש כשהחיבור חוזר».
      const parts = await expectAllPartsUploaded(guest.log); // все билеты с успешным PUT, индексы 0…N без пропусков
      expect(endReq?.technical_log?.recording?.failed, 'клиент сообщил незагруженные части').toEqual([]);
      expect(endReq?.technical_log?.recording?.complete).toBe(true);
      expect(guest.log.endStatus).toBe(200);
      expect(guest.log.endBody?.recording?.is_partial, 'ответ end-candidate-attempt: is_partial').toBe(false);

      const api = await openBusinessApi(business);
      const id = await candidateId(api, name);
      const { report } = await waitTranscriptAndReport(api, id);
      expect(report.recording?.is_partial, 'get_candidate_report: is_partial').toBe(false);

      // Реджект п.3–4: файл без дыры (≈ звонку, допуск 10 с), плеер без «ההקלטה חלקית», клик по последней реплике (после обрыва) — синхронно.
      const res = await checkReportPage(business, id, report);
      await expect(business.getByText(/ההקלטה חלקית/)).toHaveCount(0);
      test.info().annotations.push({
        type: 'hb',
        description: `частей ${parts} (обрыв после ${partsAtDrop}), упавших запросов в обрыв ${failedDuringOutage}, файл ${res.decodedSec.toFixed(1)} с / звонок ${report.attempt?.duration_seconds} с`,
      });
    } finally {
      await guest.browser.close();
    }
  });
});
